<?php $heading='Percakapan';$kicker='KOMUNIKASI · SELEKSI';$subtitle='Koordinasi mahasiswa dan rekruter setelah lolos seleksi administrasi.';$headingAction='<a class="button secondary" href="'.e(url('chat',$lamaran?['id'=>$lamaran['idLamaran']]:[])).'">Muat ulang pesan</a>';require ROOT.'/app/Views/components/heading.php';?>
<div class="chat-layout"><aside class="card conversation-list"><h3>Lamaran &amp; Percakapan</h3><?php foreach($percakapan as $a):if($a['statusLamaran']==='Draf')continue;$open=$a['administrasiLolos']&&!$a['perusahaanDihapus'];?><div class="conversation <?= $lamaran&&(int)$a['idLamaran']===(int)$lamaran['idLamaran']?'active':'' ?>"><?php if($open):?><a href="<?= e(url('chat',['id'=>$a['idLamaran']])) ?>"><?php endif;?><strong><?= e($currentUser['role']==='Mahasiswa'?$a['namaPerusahaan']:$a['namaMahasiswa']) ?></strong><span><?= e($a['namaLowongan']) ?></span><small><?= $open?'Buka percakapan →':'Tersedia setelah lolos administrasi' ?></small><?php if($open):?></a><?php endif;?></div><?php endforeach;?><?php if(!$percakapan):?><p class="muted">Belum ada lamaran.</p><?php endif;?></aside><section class="card chat-panel"><?php if(!$lamaran):?><div class="empty-state"><?= icon('chat') ?><h2>Pilih percakapan</h2><p>Percakapan aktif muncul setelah mahasiswa lolos tahap administrasi.</p></div><?php else:?><div class="chat-heading"><div><h2><?= e($currentUser['role']==='Mahasiswa'?$lamaran['namaPerusahaan']:$lamaran['namaMahasiswa']) ?></h2><p><?= e($lamaran['namaLowongan']) ?></p></div><?= badge($lamaran['statusLamaran']) ?></div><div class="messages"><?php if(!$pesan):?><p class="muted center">Belum ada pesan. Mulai percakapan untuk koordinasi seleksi.</p><?php endif;?><?php foreach($pesan as $m):?><article class="message <?= (int)$m['idPengirim']===(int)$currentUser['idAkun']?'mine':'' ?>"><strong><?= e($m['namaPengguna']) ?></strong><p><?= nl2br(e($m['isi'])) ?></p><small><?= tanggal($m['dikirimPada'],'d M, H:i') ?> WIB</small></article><?php endforeach;?></div><form class="message-form" method="post" action="<?= e(url('chat/kirim')) ?>"><?= csrf() ?><input type="hidden" name="idLamaran" value="<?= $lamaran['idLamaran'] ?>"><label for="message">Pesan baru</label><textarea id="message" name="isi" maxlength="4000" rows="3" required placeholder="Tulis pesanmu…"></textarea><div class="section-heading"><small class="muted">Klik Muat ulang pesan untuk membaca balasan terbaru.</small><button class="button">Kirim Pesan <?= icon('arrow') ?></button></div></form><?php endif;?></section></div>
